<template>
  <div class="setting-sidebar loop-view-sidebar">
    <div class="setting-sidebar-item">
      <div class="setting-sidebar-title">
        <el-button
          type="primary"
          size="small"
          class="submit-btn"
          @click="onTour"
          >{{ !beginTour ? "开始记录" : "停止记录" }}</el-button
        >
        <el-tooltip
          class="item"
          effect="dark"
          content="一键导游全局设置"
          placement="top-start"
        >
          <el-button
            type="default"
            icon="el-icon-s-tools"
            size="small"
            class="setting-btn"
            @click="onGlobalSet"
          ></el-button>
        </el-tooltip>
      </div>
      <div class="loop-view-sidebar-title" v-if="tourMarkers.length">
        <div class="txt">
          已添加{{ tourMarkers.length }}节点（{{ totalWaitTime }}秒）
        </div>
        <div class="clear" @click="onClear">清空</div>
      </div>
      <div class="loop-view-sidebar-list">
        <div class="body" v-if="tourMarkers.length">
          <div
            class="tour-item"
            v-for="(item, index) in tourMarkers"
            :key="index"
            @click="gotoTourMarker(item)"
            @mouseover="showCtrlButton(item.index)"
            @mouseout="hideCtrlButton(item.index)"
          >
            <div class="tour-item-index">
              <div class="tour-item-index-number">{{ item.index }}</div>
              <div
                class="tour-item-index-line"
                :class="item.lineClass"
                v-if="index + 1 <= tourMarkers.length - 1"
              ></div>
            </div>
            <div class="tour-item-label">
              <div class="tour-item-label-txt">
                {{ item.sceneTitle }}
                <div
                  class="del-btn"
                  v-show="showIndexList.indexOf(item.index) >= 0"
                  @click.stop="onDelNode(item)"
                >
                  <i class="el-icon el-icon-delete"></i>
                </div>
              </div>
              <div
                class="tour-item-label-info"
                v-if="index + 1 <= tourMarkers.length - 1"
              >
                <div class="tour-item-label-info-time">
                  <i class="el-icon el-icon-alarm-clock"></i>
                  <span>{{ item.waitTime }}″</span>
                </div>
                <div
                  class="tour-item-label-info-btn"
                  @click="onSetTourNode(item)"
                >
                  设置
                </div>
              </div>
            </div>
          </div>
        </div>
        <p class="tip">通过一键导游，让浏览者跟随你预先设置好的路线观看全景</p>
      </div>
    </div>
    <el-dialog
      title="时间线属性"
      :visible.sync="dialogFormVisible"
      width="460px"
    >
      <el-form :model="form">
        <el-form-item label="移动时间(单位：秒)" :label-width="formLabelWidth">
          <el-input
            v-model="form.waitTime"
            @input="onTimeChange"
            autocomplete="off"
            min="0"
            size="small"
            placeholder="设为0秒则直接跳转到下一章节"
          ></el-input>
        </el-form-item>
        <el-form-item label="语音讲解" :label-width="formLabelWidth">
          <div class="el-voice-item">
            <div class="text-right"><el-button type="primary" size="mini">选择音频</el-button></div>
            <div class="el-voice-item-box"></div>
            <div class="el-voice-item-set-node">
              应用到:
              <el-select
                v-model="form.nodes"
                multiple
                placeholder="选择节点"
                size="mini"
              >
                <el-option
                  v-for="item in nodes"
                  :key="item.code"
                  :label="`节点${item.index}`"
                  :value="item.code"
                >
                </el-option>
              </el-select>
            </div>
            <div class="el-voice-item-tip">
              相邻节点应用同一段语音讲解导览时将会连贯播放该讲解
            </div>
          </div>
        </el-form-item>
        <el-form-item label="文字内容" :label-width="formLabelWidth">
          <el-input
            type="textarea"
            v-model="form.content"
            placeholder="填写文字内容"
            size="small"
            rows="10"
          ></el-input>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible = false">取 消</el-button>
        <el-button type="primary" @click="onSave">确 定</el-button>
      </div>
    </el-dialog>
    <tour-global-set-dialog ref="tourGlobalSetDialog"/>
  </div>
</template>
  <script>
export default {
  name: 'LoopViewSidebar',
  data() {
    return {
      beginTour: false,
      showIndexList: [],
      dialogFormVisible: false,
      form: {
        code: null,
        waitTime: '',
        content: '',
        voice: '',
        nodes: [],
      },
      nodes: [],
      formLabelWidth: '140px',
    }
  },
  computed: {
    totalWaitTime() {
      //reduce((accumulator, currentValue) => accumulator + currentValue.val, 0)
      const time =  this.tourMarkers.reduce(
        (accumulator, currentValue) => accumulator + currentValue.waitTime,
        0
      )

      return time - this.tourMarkers[this.tourMarkers.length - 1].waitTime
    },
  },
  props: {
    productId: null,
    tourMarkers: {
      type: Array,
      default() {
        return []
      },
    },
  },
  components: {
    TourGlobalSetDialog: () => import('./TourGlobalSet.vue')
  },
  mounted() {},
  methods: {
    onClear() {
      this.$emit('clear')
      this.onTour()
    },
    onTour() {
      this.beginTour = !this.beginTour
      this.$emit('onTour', this.beginTour)
    },
    setTourSwitch(value) {
      this.beginTour = value
    },
    showCtrlButton(index) {
      this.showIndexList.push(index)
    },
    hideCtrlButton(index) {
      this.showIndexList.splice(this.showIndexList.indexOf(index), 1)
    },
    gotoTourMarker(id) {
      this.$emit('onGotoTourMarker', id)
    },
    onDelNode(item) {
      this.$emit('onDelTourMarker', item)
    },
    onSetTourNode(node) {
      this.dialogFormVisible = true
      this.beginTour = true
      this.form = Object.assign(
        {},
        {
          code: node.code,
          waitTime: node.waitTime,
          content: node.content,
          voice: node.voice,
        }
      )
    },
    onTimeChange() {
      this.form.waitTime = parseInt(this.form.waitTime, 10)
      if (isNaN(this.form.waitTime)) {
        this.form.waitTime = ''
      }
    },
    onSave() {
      this.dialogFormVisible = false
      this.$emit('onSave', this.form)
    },
    onGlobalSet() {
      this.$refs.tourGlobalSetDialog.init(this.productId)
    },
  },
}
</script>
